diff --git a/deploy-workbench/vk-mint.ts b/deploy-workbench/vk-mint.ts
new file mode 100644
index 0000000..a3762ea
--- /dev/null
+++ b/deploy-workbench/vk-mint.ts
@@ -0,0 +1,146 @@
+import * as pulumi from "@pulumi/pulumi";
+import * as aws from "@pulumi/aws";
+import { REGION, type createWorkbenchNetwork } from "./network";
+import type { GatewayDiscovery } from "./discovery";
+
+type WorkbenchNetwork = ReturnType<typeof createWorkbenchNetwork>;
+
+export const VK_MINT_FUNCTION_NAME = "bifrost-vk-mint";
+
+/**
+ * Step 2 of `docs/example-mint-function.md`: the Lambda that mints a gateway
+ * virtual key.
+ *
+ * It is reachable only through its Function URL, runs in the two private
+ * subnets, and reads the setup token from the dedicated `bifrost/vk-mint`
+ * secret. It never logs the key or the token.
+ */
+export const createVirtualKeyMint = (args: {
+  provider: aws.Provider;
+  network: WorkbenchNetwork;
+  gateway: GatewayDiscovery;
+  accountId: string;
+}) => {
+  const { provider, network, gateway, accountId } = args;
+
+  const role = new aws.iam.Role(
+    "bifrostVkMintRole",
+    {
+      name: VK_MINT_FUNCTION_NAME,
+      assumeRolePolicy: JSON.stringify({
+        Version: "2012-10-17",
+        Statement: [
+          {
+            Effect: "Allow",
+            Principal: { Service: "lambda.amazonaws.com" },
+            Action: "sts:AssumeRole",
+          },
+        ],
+      }),
+    },
+    { provider },
+  );
+
+  for (const policyArn of [
+    "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole",
+    "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole",
+  ]) {
+    new aws.iam.RolePolicyAttachment(
+      `bifrostVkMint${policyArn.split("/").pop()}`,
+      { role: role.name, policyArn },
+      { provider },
+    );
+  }
+
+  new aws.iam.RolePolicy(
+    "bifrostVkMintSecret",
+    {
+      role: role.id,
+      policy: JSON.stringify({
+        Version: "2012-10-17",
+        Statement: [
+          {
+            Effect: "Allow",
+            Action: ["secretsmanager:GetSecretValue"],
+            Resource: `arn:aws:secretsmanager:${REGION}:${accountId}:secret:bifrost/vk-mint-*`,
+          },
+        ],
+      }),
+    },
+    { provider },
+  );
+
+  const securityGroup = new aws.ec2.SecurityGroup(
+    "bifrostVkMintSecurityGroup",
+    {
+      name: "bifrost-vk-mint",
+      description: "Mint Lambda: 8080 to the task group, 443 and 53 out, no ingress.",
+      vpcId: network.vpc.id,
+      egress: [
+        {
+          protocol: "tcp",
+          fromPort: 8080,
+          toPort: 8080,
+          securityGroups: [network.taskSecurityGroup.id],
+        },
+        { protocol: "tcp", fromPort: 443, toPort: 443, cidrBlocks: ["0.0.0.0/0"] },
+        { protocol: "udp", fromPort: 53, toPort: 53, cidrBlocks: ["0.0.0.0/0"] },
+      ],
+    },
+    { provider },
+  );
+
+  // The task group admits nothing from a CIDR; the mint group is the peer.
+  new aws.vpc.SecurityGroupIngressRule(
+    "bifrostTaskIngressVkMint",
+    {
+      securityGroupId: network.taskSecurityGroup.id,
+      description: "8080 from the mint function only",
+      ipProtocol: "tcp",
+      fromPort: 8080,
+      toPort: 8080,
+      referencedSecurityGroupId: securityGroup.id,
+    },
+    { provider },
+  );
+
+  // The handler is compiled into ../dist/vk-mint by the workbench deploy
+  // workflow, the same way the delegate Lambda's archive is built.
+  const fn = new aws.lambda.Function(
+    "bifrostVkMint",
+    {
+      name: VK_MINT_FUNCTION_NAME,
+      runtime: aws.lambda.Runtime.NodeJS22dX,
+      handler: "vk-mint-handler.handler",
+      code: new pulumi.asset.FileArchive("../dist/vk-mint"),
+      role: role.arn,
+      memorySize: 256,
+      timeout: 15,
+      vpcConfig: {
+        subnetIds: network.privateSubnetIds,
+        securityGroupIds: [securityGroup.id],
+      },
+      environment: {
+        variables: {
+          GATEWAY_URL: gateway.endpoint,
+          SETUP_TOKEN_SECRET: "bifrost/vk-mint",
+        },
+      },
+    },
+    { provider },
+  );
+
+  const url = new aws.lambda.FunctionUrl(
+    "bifrostVkMintUrl",
+    { functionName: fn.name, authorizationType: "AWS_IAM" },
+    { provider },
+  );
+
+  const logGroup = new aws.cloudwatch.LogGroup(
+    "bifrostVkMintLogs",
+    { name: `/aws/lambda/${VK_MINT_FUNCTION_NAME}`, retentionInDays: 30 },
+    { provider },
+  );
+
+  return { fn, url, logGroup };
+};
